package io.lumine.mythic.lib.api.crafting.ingredients; import net.minecraft.item.ItemStack; import java.util.*; public class ShapelessItem implements Cloneable { private final int id,x,y,original; private final ItemStack stack; private int taken; private final HashMap<Integer,ShapelessRequester> requesters=new HashMap<>(); public ShapelessItem(int id,ItemStack stack,int x,int y){this.id=id;this.stack=stack.copy();this.original=stack.getCount();this.x=x;this.y=y;} public ItemStack getStack(){return stack.copy();} public void take(int n){taken=Math.min(original,taken+Math.max(0,n));} public int getTaken(){return taken;} public int getAmount(){return original-taken;} public int getOriginalAmount(){return original;} public int getOperationalIdentifier(){return id;} public int getOriginalWidthCoord(){return x;} public int getOriginalHeightCoord(){return y;} public void claimDibs(ShapelessRequester r){requesters.put(r.getRequestIdentifier(),r);} public HashMap<Integer,ShapelessRequester> getRequesters(){return new HashMap<>(requesters);} public ShapelessItem clone(){ShapelessItem c=new ShapelessItem(id,stack,x,y);c.taken=taken;return c;} public ShapelessItem completeClone(){ShapelessItem c=clone();c.requesters.putAll(requesters);return c;} public static ArrayList<ShapelessItem> deepCloneList(ArrayList<ShapelessItem> in){ArrayList<ShapelessItem> o=new ArrayList<>();in.forEach(i->o.add(i.clone()));return o;} public static ArrayList<ShapelessItem> completeCloneList(ArrayList<ShapelessItem> in){ArrayList<ShapelessItem> o=new ArrayList<>();in.forEach(i->o.add(i.completeClone()));return o;} }
